import {PosJson} from 'shared';
import {DocRaw} from '../../types/doc-raw';
import {validatePosOpoldf} from './validate-pos-opoldf';
import {DocumentError} from '../../errors/document-error';

// these tests were entirely generated by claude. Adapted by me.

// mock raw positions
const posRaws = (...lineNrs: number[]): DocRaw[] => lineNrs.map(lineNr => ({lineNr, type: 'POS'}) as DocRaw);
// mock posJsons
const posJsons = (...ids: string[]): PosJson[] => ids.map(OPOLDF => ({OPOLDF}) as PosJson);

describe('validatePosOpoldf', () => {
    it('accepts ascending values with gaps', () => {
        expect(() => validatePosOpoldf(posRaws(10, 11, 12, 13), posJsons('1', '2', '5', '6'))).not.toThrow();
    });

    it('accepts any starting point', () => {
        expect(() => validatePosOpoldf(posRaws(10, 11), posJsons('4', '5'))).not.toThrow();
    });

    it('accepts a single position', () => {
        expect(() => validatePosOpoldf(posRaws(10), posJsons('7'))).not.toThrow();
    });

    it('rejects descending values', () => {
        expect(() => validatePosOpoldf(posRaws(10, 11), posJsons('2', '1'))).toThrow(DocumentError);
    });

    it('rejects duplicate values', () => {
        expect(() => validatePosOpoldf(posRaws(10, 11), posJsons('2', '2'))).toThrow(DocumentError);
    });

    it('reports the line of the offending position', () => {
        expect(() => validatePosOpoldf(posRaws(10, 11), posJsons('2', '1'))).toThrow('Zeile 11 (POS)');
    });
});